param()

$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "============================================================" -ForegroundColor DarkYellow
Write-Host " HOGWARTS PRODUCT V2 - MOBILE FINAL FIX" -ForegroundColor Yellow
Write-Host " Menus + HUD + World + Cards + Combat + Modals" -ForegroundColor Gray
Write-Host "============================================================" -ForegroundColor DarkYellow
Write-Host ""

$root = Get-Location

$required = @(
    "index.html",
    "product\product-v2.css",
    "product\client-product-v2.js"
)

foreach ($file in $required) {
    if (!(Test-Path (Join-Path $root $file))) {
        throw "Este hotfix deve ser executado sobre o Product V2 aplicado. Faltou: $file"
    }
}

if (-not (Get-Command node -ErrorAction SilentlyContinue)) {
    throw "Node.js nao foi encontrado no PATH."
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $root ".hogwarts-mobile-v2-backup-$stamp"
New-Item -ItemType Directory -Path $backup -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $backup "product") -Force | Out-Null

Copy-Item "index.html" (Join-Path $backup "index.html") -Force
Copy-Item "product\product-v2.css" (Join-Path $backup "product\product-v2.css") -Force

if (Test-Path "product\mobile-product-v2.css") {
    Copy-Item "product\mobile-product-v2.css" (Join-Path $backup "product\mobile-product-v2.css") -Force
}
if (Test-Path "product\mobile-product-v2.js") {
    Copy-Item "product\mobile-product-v2.js" (Join-Path $backup "product\mobile-product-v2.js") -Force
}

Write-Host "[1/4] Backup mobile criado." -ForegroundColor Cyan

$patcherPath = Join-Path $root ".mobile-v2-patcher.js"
$bytes = [Convert]::FromBase64String("")
[IO.File]::WriteAllBytes($patcherPath, $bytes)

try {
    Write-Host "[2/4] Instalando layout mobile final..." -ForegroundColor Cyan
    node $patcherPath
    if ($LASTEXITCODE -ne 0) { throw "Falha no transformador mobile." }

    Write-Host "[3/4] Validando JavaScript mobile..." -ForegroundColor Cyan
    node --check "product\mobile-product-v2.js"
    if ($LASTEXITCODE -ne 0) { throw "Erro de sintaxe em mobile-product-v2.js" }

    Write-Host "[4/4] Validando integracao..." -ForegroundColor Cyan
    $html = Get-Content "index.html" -Raw
    $css = Get-Content "product\mobile-product-v2.css" -Raw

    if ($html -notmatch "/product/mobile-product-v2.css") {
        throw "CSS mobile nao foi vinculado ao index.html."
    }
    if ($html -notmatch "/product/mobile-product-v2.js") {
        throw "JS mobile nao foi vinculado ao index.html."
    }
    if ($css -notmatch "\.sub-tabs\.oculto") {
        throw "Protecao de menus ocultos nao foi instalada."
    }

    $rollback = @"
param()
`$ErrorActionPreference = "Stop"
`$root = Split-Path -Parent `$MyInvocation.MyCommand.Path
`$backup = "$backup"

if (!(Test-Path `$backup)) { throw "Backup nao encontrado: `$backup" }

Copy-Item (Join-Path `$backup "index.html") (Join-Path `$root "index.html") -Force
Copy-Item (Join-Path `$backup "product\product-v2.css") (Join-Path `$root "product\product-v2.css") -Force

`$oldCss = Join-Path `$backup "product\mobile-product-v2.css"
`$oldJs  = Join-Path `$backup "product\mobile-product-v2.js"

if (Test-Path `$oldCss) {
    Copy-Item `$oldCss (Join-Path `$root "product\mobile-product-v2.css") -Force
} elseif (Test-Path (Join-Path `$root "product\mobile-product-v2.css")) {
    Remove-Item (Join-Path `$root "product\mobile-product-v2.css") -Force
}

if (Test-Path `$oldJs) {
    Copy-Item `$oldJs (Join-Path `$root "product\mobile-product-v2.js") -Force
} elseif (Test-Path (Join-Path `$root "product\mobile-product-v2.js")) {
    Remove-Item (Join-Path `$root "product\mobile-product-v2.js") -Force
}

Write-Host "Rollback mobile concluido." -ForegroundColor Yellow
"@

    [IO.File]::WriteAllText(
        (Join-Path $root "ROLLBACK_HOGWARTS_MOBILE_V2.ps1"),
        $rollback,
        (New-Object Text.UTF8Encoding($false))
    )

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " MOBILE V2 CORRIGIDO E REORGANIZADO" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "Importante no celular:" -ForegroundColor White
    Write-Host "  Feche a aba antiga e abra novamente." -ForegroundColor Gray
    Write-Host "  Se o navegador mantiver CSS em cache, recarregue a pagina sem cache." -ForegroundColor Gray
}
finally {
    if (Test-Path $patcherPath) {
        Remove-Item $patcherPath -Force -ErrorAction SilentlyContinue
    }
}
